def unique_jobs(rows):
    result = []
    seen = {}
    for row in rows:
        source = row.get('source')
        source_id = row.get('source_id')
        # Missing/None/empty source_id means keep the row separately
        if source_id is None or source_id == '':
            result.append(row)
        else:
            key = (source, source_id)
            if key in seen:
                # duplicate with valid source_id, skip
                continue
            else:
                result.append(row)
                seen[key] = True
    return result

